create table app_users(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, full_name varchar(255) not null, email varchar(255) not null unique, phone varchar(255), password_hash varchar(255) not null, role varchar(50) not null, active boolean not null);
create table categories(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, name varchar(255) not null unique, slug varchar(255) not null unique, icon varchar(255), image_url varchar(500), active boolean not null, display_order integer);
create table brands(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, name varchar(255) not null unique, logo_url varchar(500), active boolean not null);
create table vendors(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, name varchar(255) not null, logo_url varchar(500), phone varchar(255), whatsapp varchar(255), address varchar(500), district varchar(255), description varchar(1000), active boolean not null);
create table products(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, sku varchar(255) not null unique, name varchar(255) not null, slug varchar(255) not null unique, short_description varchar(500), description text, price numeric(14,2) not null, promo_price numeric(14,2), stock integer not null, low_stock_threshold integer not null, unit varchar(100) not null, main_image_url varchar(500), category_id bigint not null references categories(id), brand_id bigint references brands(id), vendor_id bigint references vendors(id), active boolean not null, featured boolean not null, best_seller boolean not null, rating double precision not null, review_count integer not null);
create table product_images(product_id bigint not null references products(id) on delete cascade, image_url varchar(500));
create table advertisements(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, title varchar(255) not null, subtitle varchar(500), image_url varchar(500), target_url varchar(500), placement varchar(100) not null, starts_at timestamptz, ends_at timestamptz, active boolean not null);
create table customer_orders(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, order_number varchar(255) not null unique, customer_id bigint not null references app_users(id), status varchar(80) not null, subtotal numeric(14,2) not null, delivery_fee numeric(14,2) not null, total numeric(14,2) not null, delivery_address varchar(500) not null, delivery_district varchar(255), customer_phone varchar(255), payment_method varchar(100), tracking_code varchar(255));
create table order_items(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, order_id bigint not null references customer_orders(id) on delete cascade, product_id bigint not null references products(id), quantity integer not null, unit_price numeric(14,2) not null, line_total numeric(14,2) not null);
create table payments(id bigserial primary key, created_at timestamptz not null, updated_at timestamptz not null, order_id bigint not null unique references customer_orders(id), method varchar(100) not null, status varchar(50) not null, amount numeric(14,2) not null, provider_reference varchar(255));
create index idx_product_category on products(category_id); create index idx_product_name on products(lower(name)); create index idx_order_customer on customer_orders(customer_id);
